import backtrader as bt


class MeanReversionStrategy(bt.Strategy):
    def __init__(self):
        self.ema = bt.indicators.ExponentialMovingAverage(self.data.close, period=20)
        self.bb_2 = bt.indicators.BollingerBands(
            self.data.close, period=20, devfactor=2.0
        )
        self.atr = bt.indicators.AverageTrueRange(self.data, period=14)
        self.atr_sma = bt.indicators.SimpleMovingAverage(self.atr, period=60)
        self.volume_sma = bt.indicators.SimpleMovingAverage(
            self.data.volume, period=20
        )
        self.bb_05 = bt.indicators.BollingerBands(
            self.data.close, period=20, devfactor=0.5
        )

        self.sigma = (self.bb_2.top - self.bb_2.mid) / 2.0
        self.strike_lower_2 = self.ema - 2.0 * self.sigma
        self.strike_lower_1 = self.ema - self.sigma
        self.strike_upper_1 = self.ema + self.sigma
        self.strike_upper_2 = self.ema + 2.0 * self.sigma

        self.cross_lower_up = bt.indicators.CrossUp(self.data.close, self.bb_2.bot)
        self.cross_upper_down = bt.indicators.CrossDown(
            self.data.close, self.bb_2.top
        )

        self.order = None
        self.stop_order = None
        self.entry_bar = None
        self.pending_stop_price = None
        self.peak_value = self.broker.getvalue()
        self.trading_stopped = False

    def notify_order(self, order):
        if order.status == order.Completed:
            if order is self.order:
                self.order = None
                if order.isbuy() or order.issell():
                    if self.position:
                        self.entry_bar = len(self)
                        self.stop_order = self.sell(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=self.pending_stop_price,
                        ) if self.position.size > 0 else self.buy(
                            size=abs(self.position.size),
                            exectype=bt.Order.Stop,
                            price=self.pending_stop_price,
                        )
                    else:
                        self.entry_bar = None
                        self.pending_stop_price = None
            elif order is self.stop_order:
                self.stop_order = None
                self.entry_bar = None
                self.pending_stop_price = None
        elif order.status in (order.Canceled, order.Margin, order.Rejected):
            if order is self.order:
                self.order = None
                self.pending_stop_price = None
            if order is self.stop_order:
                self.stop_order = None

    def _close_position(self):
        if self.stop_order is not None:
            self.cancel(self.stop_order)
            self.stop_order = None
        self.order = self.close()

    def next(self):
        value = self.broker.getvalue()
        self.peak_value = max(self.peak_value, value)
        if (self.peak_value - value) / self.peak_value >= 0.10:
            self.trading_stopped = True

        if self.trading_stopped:
            if self.order is not None:
                if not self.position:
                    self.cancel(self.order)
                return
            if self.position:
                self._close_position()
            return

        if self.order is not None:
            return

        if self.position:
            returned_inside = (
                self.data.close[0] > self.bb_05.bot[0]
                and self.data.close[0] < self.bb_05.top[0]
            )
            expired = self.entry_bar is not None and len(self) - self.entry_bar >= 20
            if returned_inside or expired:
                self._close_position()
            return

        volatility_ok = self.atr[0] <= 1.5 * self.atr_sma[0]
        volume_ok = self.data.volume[0] >= self.volume_sma[0]
        no_gap = abs(self.data.open[0] - self.data.close[-1]) <= 1.5 * self.atr[0]
        if not (volatility_ok and volume_ok and no_gap):
            return

        if self.cross_lower_up[0]:
            stop_price = self.ema[0] - 2.0 * self.atr[0]
            risk_per_share = self.data.close[0] - stop_price
            if risk_per_share > 0:
                size = int((0.05 * value) / risk_per_share)
                if size > 0:
                    self.pending_stop_price = stop_price
                    self.order = self.buy(size=size)
        elif self.cross_upper_down[0]:
            stop_price = self.ema[0] + 2.0 * self.atr[0]
            risk_per_share = stop_price - self.data.close[0]
            if risk_per_share > 0:
                size = int((0.05 * value) / risk_per_share)
                if size > 0:
                    self.pending_stop_price = stop_price
                    self.order = self.sell(size=size)
